const dialog=document.querySelector('dialog');const projects=[['无境项目合同管理后台','面向项目合同管理场景的后台产品体验设计。'],['智能问答','围绕智能问答场景的产品体验设计项目。'],['车载 HMI','面向车载场景的人机交互设计项目。']];document.querySelectorAll('[data-project]').forEach(button=>button.addEventListener('click',()=>{const project=projects[Number(button.dataset.project)];document.querySelector('#dialog-title').textContent=project[0];document.querySelector('#dialog-description').textContent=project[1];dialog.showModal()}));document.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close()}});document.querySelector('#year').textContent=new Date().getFullYear();const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){document.querySelectorAll('nav a').forEach(link=>link.classList.toggle('active',link.hash==='#'+entry.target.id))}}),{rootMargin:'-15% 0px -55% 0px'});document.querySelectorAll('#home,#expertise,#projects').forEach(section=>observer.observe(section));
